import sys

def minion_game(s):
    vowels = 'AEIOU'
    stuart_score = 0
    kevin_score = 0
    n = len(s)

    for i in range(n):
        if s[i] in vowels:
            kevin_score += n - i
        else:
            stuart_score += n - i

    if stuart_score > kevin_score:
        print(f"Stuart {stuart_score}")
    elif kevin_score > stuart_score:
        print(f"Kevin {kevin_score}")
    else:
        print("Draw")

if __name__ == "__main__":
    s = sys.stdin.read().strip()
    minion_game(s)
